-- Staging-only migration 216: qualify supervised rule list output columns.
begin;set local lock_timeout='10s';set local statement_timeout='180s';select pg_advisory_xact_lock(hashtextextended('pdc-staging-migration-216-supervised-list-qualification',0));select public.pdc_monitor_staging_guard();do $guard$ begin if not public.pdc_monitor_staging_guard() or not exists(select 1 from public.pdc_staging_environment_sentinel where singleton and project_ref='cdsmnqxtyyoeoznmbidd') or to_regclass('public.pdc_production_environment_sentinel') is not null or not exists(select 1 from supabase_migrations.schema_migrations where version='215' and name='telegram_supervised_command_completeness') or exists(select 1 from supabase_migrations.schema_migrations where version~'^[0-9]+$' and version::integer>215) or exists(select 1 from supabase_migrations.schema_migrations where version='216') then raise exception 'PDC_216_STAGING_OR_LEDGER_MISMATCH' using errcode='55000';end if;end $guard$;
create or replace function public.list_pdc_supervised_rules_213(p_include_history boolean default false) returns table(family_id uuid,family_key text,version_id uuid,version_no integer,state text,match_kind text,operation_code text,normalized_description text,phrase_category text,work_key text,priority integer,confidence numeric,effective_from timestamptz,effective_until timestamptz,revision bigint) language plpgsql stable security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();begin if not coalesce((s->>'ok')::boolean,false) then s:=public.pdc_supervised_monitor_scope_213();end if;if not coalesce((s->>'ok')::boolean,false) then raise insufficient_privilege using message='supervised_rule_read_required';end if;return query with latest_event as(select distinct on(ev.version_id) ev.version_id,ev.event_kind from public.pdc_supervised_rule_events ev order by ev.version_id,ev.created_at desc,ev.event_id desc) select f.family_id,f.family_key,v.version_id,v.version_no,coalesce(le.event_kind,'proposed'),v.match_kind,v.operation_code,v.normalized_description,v.phrase_category,v.work_key,v.priority,v.confidence,v.effective_from,v.effective_until,rev.revision from public.pdc_supervised_rule_families f join public.pdc_supervised_rule_versions v on v.family_id=f.family_id left join latest_event le on le.version_id=v.version_id cross join public.pdc_supervised_revision rev where p_include_history or (le.event_kind='activated' and v.effective_from<=clock_timestamp() and (v.effective_until is null or v.effective_until>clock_timestamp())) order by f.family_key,v.version_no desc;end$$;
revoke all on function public.list_pdc_supervised_rules_213(boolean) from public,anon,authenticated,service_role;grant execute on function public.list_pdc_supervised_rules_213(boolean) to authenticated;insert into supabase_migrations.schema_migrations(version,name,statements) values('216','supervised_rule_list_column_qualification',array['fully qualify event and output columns to avoid PL/pgSQL output-variable ambiguity']);notify pgrst,'reload schema';commit;
